// Illustrative contracts and references. No host environment is accessed.
const inputContracts=[
{region:{type:'string',title:'区域',required:true},format:{type:'string',title:'输出格式'},period:{type:'string',title:'统计周期'},channels:{type:'array',title:'渠道列表'}},
{environment:{type:'string',title:'目标环境',required:true},timeout:{type:'integer',title:'超时（秒）'},mode:{type:'string',title:'检查模式'}},
{status:{type:'string',title:'订单状态'},period:{type:'string',title:'时间范围'},limit:{type:'integer',title:'数量上限'}}
];
const exampleRefs=[{source:'environment',name:'ORCHARD_REGION',type:'string'},{source:'environment',name:'TARGET_ENV',type:'string'},{source:'environment',name:'REQUEST_TIMEOUT',type:'integer'},{source:'dictionary',dictionaryId:'demo-config',key:'region',type:'string'}];
let parameterMode='form',parameterSources={};
const inputLabel=$('editInput').parentElement;
inputLabel.insertAdjacentHTML('beforebegin','<div class="parameter-tabs" aria-label="参数录入方式"><button type="button" id="paramsForm">参数表单</button><button type="button" id="paramsJson">JSON</button></div><p class="muted" id="contractNote"></p><div id="parameterFields"></div>');
inputLabel.insertAdjacentHTML('afterend','<p class="muted" id="sourceHint"></p>');
inputLabel.firstChild.textContent='参数 JSON';
$('editInput').closest('.dialog-body').querySelectorAll('p.muted').forEach(p=>{if(p.textContent.includes('原型只验证 JSON'))p.textContent='原型验证示例字段类型和必填项；正式版按目标完整 JSON Schema 校验。引用仅保存名称，不读取真实环境。关闭或 Esc 保留已保存配置。'});
function sourceLabel(ref){return ref.source==='environment'?`env:${ref.name}`:`dictionary:${ref.dictionaryId}:${ref.key}`}
function parseParameters(){const v=JSON.parse($('editInput').value);if(!v||typeof v!=='object'||Array.isArray(v))throw Error('参数必须是 JSON 对象。');return v}
function parameterError(message){$('formError').textContent=message;return false}
function validateParameters(){try{const v=parseParameters(),fields=inputContracts[Number($('editTarget').value)];for(const [key,f] of Object.entries(fields)){if(parameterSources[key]){if(parameterSources[key].type!==f.type)throw Error(`${key}：引用类型与字段不匹配。`);continue}if(f.required&&(v[key]===undefined||v[key]===''))throw Error(`${key}：请填写必填参数或引入环境变量。`);if(v[key]===undefined)continue;const good=f.type==='array'?Array.isArray(v[key]):f.type==='integer'?Number.isInteger(v[key]):typeof v[key]===f.type;if(!good)throw Error(`${key}：需要 ${f.type} 类型。`)}for(const key of Object.keys(parameterSources))if(!fields[key])throw Error(`${key}：新目标未声明此引用字段，请切回表单解除引用。`);return true}catch(e){return parameterError(e.message)}}
function drawParameters(){let value;try{value=parseParameters()}catch(e){parameterMode='json';value={}}
const fields=inputContracts[Number($('editTarget').value)];$('paramsForm').setAttribute('aria-pressed',String(parameterMode==='form'));$('paramsJson').setAttribute('aria-pressed',String(parameterMode==='json'));inputLabel.classList.toggle('hidden',parameterMode!=='json');$('parameterFields').classList.toggle('hidden',parameterMode!=='form');$('contractNote').textContent='';
$('parameterFields').innerHTML=Object.entries({...fields,...Object.fromEntries(Object.keys(parameterSources).filter(k=>!fields[k]).map(k=>[k,{type:'unknown',title:'目标未声明的引用'}]))}).map(([key,f])=>{const ref=parameterSources[key],v=value[key],text=v===undefined?'':f.type==='string'?v:JSON.stringify(v);return `<div class="parameter-row"><label for="param-${key}">${esc(f.title)} <code>${key}</code>${f.required?' *':''}</label><div class="parameter-controls">${ref?`<button type="button" id="param-${key}" class="reference-value" data-pick="${key}" title="点击更换引用">{{${esc(sourceLabel(ref))}}}</button>`:f.type==='array'?`<textarea id="param-${key}" data-param="${key}" class="mono" rows="3" placeholder="JSON 数组">${esc(text)}</textarea>`:`<input id="param-${key}" data-param="${key}" value="${esc(text)}" placeholder="${f.type}" ${f.type==='integer'?'type="number" step="1"':''}>`}<button type="button" class="parameter-icon" ${ref?'data-unbind':'data-pick'}="${key}" aria-label="${ref?'解除引用':'引入环境变量'} ${key}" title="${ref?'解除引用':'引入环境变量'}">${ref?unlinkIcon:bookIcon}</button></div></div>`}).join('');
$('sourceHint').textContent=Object.keys(parameterSources).length?'已绑定：'+Object.entries(parameterSources).map(([k,r])=>`${k} ← ${sourceLabel(r)}`).join('；')+'。解除引用后可手动填写。':'';}
function collectForm(){if(parameterMode!=='form')return true;try{const value=parseParameters(),fields=inputContracts[Number($('editTarget').value)];for(const el of $('parameterFields').querySelectorAll('[data-param]')){const key=el.dataset.param,raw=el.value,f=fields[key];if(raw===''){delete value[key];continue}if(f.type==='string')value[key]=raw;else if(f.type==='integer'){const number=Number(raw);if(!Number.isInteger(number))throw Error(`${key}：请输入整数。`);value[key]=number}else{const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error(`${key}：请输入 JSON 数组。`);value[key]=parsed}}$('editInput').value=JSON.stringify(value,null,2);return true}catch(e){return parameterError(e.message)}}
$('paramsJson').onclick=()=>{if(!collectForm())return;parameterMode='json';$('formError').textContent='';drawParameters()};
$('paramsForm').onclick=()=>{try{parseParameters()}catch{return parameterError('请先修正 JSON 对象；原始输入已保留。')}parameterMode='form';$('formError').textContent='';drawParameters()};
$('parameterFields').onclick=e=>{const pick=e.target.closest('[data-pick]'),unbind=e.target.closest('[data-unbind]');if(pick){if(collectForm())openReferencePicker(pick.dataset.pick)}if(unbind){if(!collectForm())return;const key=unbind.dataset.unbind;delete parameterSources[key];drawParameters();$('param-'+key).focus()}};
const originalOpenEditor=openEditor;openEditor=function(id=null){originalOpenEditor(id);parameterSources=JSON.parse(JSON.stringify(items.find(x=>x.id===id)?.inputSources||{}));parameterMode='form';drawParameters()};
$('editTarget').onchange=()=>{if(parameterMode==='form'){
// Retain visible edits using the previous target's field types before rendering the new contract.
const next=$('editTarget').value;$('editTarget').value=String(lastParameterTarget);const ok=collectForm();$('editTarget').value=next;if(!ok){$('editTarget').value=String(lastParameterTarget);return}}
lastParameterTarget=Number($('editTarget').value);drawParameters();parameterError('目标已切换，原参数和引用已保留，请按新输入定义核对后保存。')};
let lastParameterTarget=0;const openWithParameters=openEditor;openEditor=function(id=null){openWithParameters(id);lastParameterTarget=Number($('editTarget').value)};
const originalSave=$('form').onsubmit;$('form').onsubmit=e=>{e.preventDefault();if(!collectForm()||!validateParameters())return;const value=parseParameters();for(const key of Object.keys(parameterSources))delete value[key];$('editInput').value=JSON.stringify(value,null,2);const id=editing;originalSave(e);if(!$('editor').open){const item=id?items.find(x=>x.id===id):items.at(-1);item.inputSources=JSON.parse(JSON.stringify(parameterSources));if(selected)detail()}};
const originalDetail=detail;detail=function(){originalDetail();const x=items.find(x=>x.id===selected);if(x?.inputSources&&Object.keys(x.inputSources).length)$('detailBody').insertAdjacentHTML('beforeend',`<h2>参数来源（执行时解析）</h2><pre>${esc(JSON.stringify(x.inputSources,null,2))}</pre>`)};
const originalRecordStart=recordStart;recordStart=function(x){const r=originalRecordStart(x);r.inputSources=JSON.parse(JSON.stringify(x.inputSources||{}));return r};
const originalShowRecord=showRecord;showRecord=function(id,open=true){originalShowRecord(id,open);const r=records.find(x=>x.id===id);if(r?.inputSources&&Object.keys(r.inputSources).length)$('runBody').insertAdjacentHTML('beforeend',`<h2>参数引用</h2><pre>${esc(JSON.stringify(r.inputSources,null,2))}</pre>`)};

const bookIcon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 7v14m0-14C8 4 4 4 2 5v15c3-1 6-1 10 1 4-2 7-2 10-1V5c-3-1-7-1-10 2Z"/></svg>';
const unlinkIcon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="m3 3 18 18M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-1 1M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l1-1"/></svg>';
document.body.insertAdjacentHTML('beforeend','<dialog id="referencePicker" aria-labelledby="referenceTitle"><div class="dialog-head"><h2 id="referenceTitle">引入环境变量</h2><button type="button" id="referenceClose" aria-label="关闭引用选择器">✕</button></div><div class="dialog-body"><p class="muted">选择来源，点击类型匹配的变量即可引用。仅展示名称和类型，不展示值。</p><div class="reference-columns"><section><label for="referenceSourceSearch">来源</label><input id="referenceSourceSearch" placeholder="搜索来源…"><div id="referenceSources"></div></section><section><label for="referenceKeySearch">变量 / Key</label><input id="referenceKeySearch" placeholder="搜索变量或 Key…"><div id="referenceKeys"></div></section></div></div><div class="dialog-footer"><button type="button" id="referenceCancel">取消</button></div></dialog>');
let referenceField='',referenceSource='environment';
function renderReferencePicker(){const sources=[['environment','环境变量'],['dictionary','配置字典']];const sourceQuery=$('referenceSourceSearch').value.trim().toLowerCase();$('referenceSources').innerHTML=sources.filter(([id,label])=>label.toLowerCase().includes(sourceQuery)||id.includes(sourceQuery)).map(([id,label])=>`<button type="button" data-ref-source="${id}" aria-pressed="${id===referenceSource}">${label}</button>`).join('')||'<p class="muted">没有匹配的来源。</p>';const field=inputContracts[Number($('editTarget').value)][referenceField],query=$('referenceKeySearch').value.trim().toLowerCase();$('referenceKeys').innerHTML=exampleRefs.map((r,i)=>({r,i})).filter(({r})=>r.source===referenceSource&&(r.name||r.key).toLowerCase().includes(query)).map(({r,i})=>`<button type="button" data-ref-index="${i}" ${r.type!==field?.type?'disabled':''}><span>${esc(r.name||r.key)}</span><small>${r.type}${r.type!==field?.type?' · 类型不匹配':''}</small></button>`).join('')||'<p class="muted">没有匹配的变量 / Key。</p>'}
function openReferencePicker(key){referenceField=key;referenceSource=parameterSources[key]?.source||referenceSource;$('referenceTitle').textContent='引入环境变量 · '+key;$('referenceSourceSearch').value='';$('referenceKeySearch').value='';renderReferencePicker();$('referencePicker').showModal();$('referenceSourceSearch').focus()}
function closeReferencePicker(){ $('referencePicker').close() }
$('referenceClose').onclick=closeReferencePicker;$('referenceCancel').onclick=closeReferencePicker;
$('referencePicker').addEventListener('close',()=>{const button=[...$('parameterFields').querySelectorAll('[data-pick],[data-unbind]')].find(b=>b.dataset.pick===referenceField||b.dataset.unbind===referenceField);button?.focus()});
$('referenceSourceSearch').oninput=renderReferencePicker;$('referenceKeySearch').oninput=renderReferencePicker;
$('referenceSources').onclick=e=>{const b=e.target.closest('[data-ref-source]');if(b){referenceSource=b.dataset.refSource;$('referenceKeySearch').value='';renderReferencePicker()}};
$('referenceKeys').onclick=e=>{const b=e.target.closest('[data-ref-index]');if(!b||b.disabled)return;parameterSources[referenceField]={...exampleRefs[Number(b.dataset.refIndex)]};const value=parseParameters();delete value[referenceField];$('editInput').value=JSON.stringify(value,null,2);drawParameters();closeReferencePicker()};
